package typeinfo

// PreserveAdaptiveEncoding returns the fresh TypeInfo with its storage encoding pinned to the
// existing TypeInfo's encoding, when both represent the same type family. This prevents a
// freshly-constructed TypeInfo from silently adopting the global adaptive-encoding default when the
// column was originally persisted under a legacy address encoding.
//
// It acts as a no-op (returns fresh unchanged) when existing is nil, when the two TypeInfos belong
// to different type families (e.g. VARCHAR to TEXT, Point to LineString), or when the type family
// does not use variable adaptive encoding (e.g. integer types). It returns nil when fresh is nil.
//
// The covered type families are string/text (blobStringType), binary/blob (varBinaryType), JSON
// (jsonType), and each concrete geometry type (pointType, linestringType, polygonType,
// multipointType, multilinestringType, multipolygonType, geomcollType, geometryType). A match
// requires that existing and fresh share the same concrete type; the persisted encoding is never
// carried across a type-family boundary.
func PreserveAdaptiveEncoding(existing TypeInfo, fresh TypeInfo) TypeInfo {
	if existing == nil || fresh == nil {
		return fresh
	}

	switch existing.(type) {
	case *blobStringType:
		if _, ok := fresh.(*blobStringType); ok {
			return fresh.WithEncoding(existing.Encoding())
		}
	case *varBinaryType:
		if _, ok := fresh.(*varBinaryType); ok {
			return fresh.WithEncoding(existing.Encoding())
		}
	case *jsonType:
		if _, ok := fresh.(*jsonType); ok {
			return fresh.WithEncoding(existing.Encoding())
		}
	case *pointType:
		if _, ok := fresh.(*pointType); ok {
			return fresh.WithEncoding(existing.Encoding())
		}
	case *linestringType:
		if _, ok := fresh.(*linestringType); ok {
			return fresh.WithEncoding(existing.Encoding())
		}
	case *polygonType:
		if _, ok := fresh.(*polygonType); ok {
			return fresh.WithEncoding(existing.Encoding())
		}
	case *multipointType:
		if _, ok := fresh.(*multipointType); ok {
			return fresh.WithEncoding(existing.Encoding())
		}
	case *multilinestringType:
		if _, ok := fresh.(*multilinestringType); ok {
			return fresh.WithEncoding(existing.Encoding())
		}
	case *multipolygonType:
		if _, ok := fresh.(*multipolygonType); ok {
			return fresh.WithEncoding(existing.Encoding())
		}
	case *geomcollType:
		if _, ok := fresh.(*geomcollType); ok {
			return fresh.WithEncoding(existing.Encoding())
		}
	case *geometryType:
		if _, ok := fresh.(*geometryType); ok {
			return fresh.WithEncoding(existing.Encoding())
		}
	}

	return fresh
}
