			cols[i].TypeInfo = preserved
			changed = true
		}
	}

	if !changed {
		return newSch, nil
	}

	newCols := schema.NewColCollection(cols...)
	return schema.NewSchema(newCols, newSch.GetPkOrdinals(), newSch.GetCollation(), newSch.Indexes(), newSch.Checks())
